// Steam
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
for (let i = 0; i < 20; i++) {
    const angle = (i / 20) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 140;
    const y = 200 + Math.sin(angle) * 140;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + 5, y - 5);
    ctx.stroke();
}

